(()=>{
  const imgs = [...document.images].map(i => ({w: i.naturalWidth, h: i.naturalHeight, shown: Math.round(i.getBoundingClientRect().width)}));
  return JSON.stringify({images: imgs, imageCount: imgs.length, allLoaded: imgs.length > 0 && imgs.every(i => i.w > 0), fontCount: document.fonts.size});
})()

(()=>{
  const h = [...document.querySelectorAll('h2')].find(x => /What was wrong/.test(x.textContent));
  if (!h) return JSON.stringify({error: 'register heading not found'});
  const y = Math.round(h.getBoundingClientRect().top + window.scrollY);
  window.scrollTo(0, y - 24);
  return JSON.stringify({scrolledTo: y - 24});
})()

(()=>{
  const rows = [...document.querySelectorAll('tbody tr')];
  const r = rows.find(x => /^code\.diff\b/.test(x.textContent.replace(/\s+/g,' ').trim()));
  if (!r) return JSON.stringify({error: 'the code.diff row was not found'});
  const y = Math.round(r.getBoundingClientRect().top + window.scrollY);
  window.scrollTo(0, y - 24);
  return JSON.stringify({scrolledTo: y - 24, firstRows: rows.slice(0, 3).map(x => x.textContent.replace(/\s+/g,' ').trim().slice(0, 48))});
})()

(()=>{
  const h = [...document.querySelectorAll('h3')].find(x => /re-driven at the committed revision/.test(x.textContent));
  if (!h) return JSON.stringify({error: 'recheck heading not found'});
  const y = Math.round(h.getBoundingClientRect().top + window.scrollY);
  window.scrollTo(0, y - 40);
  return JSON.stringify({scrolledTo: y, heading: h.textContent.trim()});
})()

(()=>{
  window.scrollTo(0,0);
  const over = [...document.querySelectorAll('*')].filter(e => e.getBoundingClientRect().width > document.documentElement.clientWidth + 2).map(e => e.tagName + '.' + e.className).slice(0, 8);
  return JSON.stringify({narrowOverflow: document.documentElement.scrollWidth > document.documentElement.clientWidth + 1, over});
})()
